const QA = [
  { type: 'placeholders', label: 'Placeholders', tr: true, skipHtml: false },
  { type: 'html', label: 'HTML', tr: true, skipHtml: false },
  { type: 'inline_code', label: 'Missing inline code', tr: true, skipHtml: false },
  { type: 'double_space', label: 'Double space', tr: true, skipHtml: true }
];

function isHtmlProject(name) {
  const s = (name || '').toLowerCase();
  return s.indexOf('html') >= 0 || s.indexOf('legal page') >= 0;
}

const out = [];
let first = true;
for (const it of items) {
  for (const p of (it.json.projects || [])) {
    const base = (p.base_language_iso || 'en').toLowerCase();
    const htmlProject = isHtmlProject(p.name);
    for (const q of QA) {
      if (q.skipHtml && htmlProject) { continue; }
      out.push({ json: {
        project_id: p.project_id,
        project_name: p.name,
        base_lang: base,
        qa_type: q.type,
        qa_label: q.label,
        extra: q.tr ? '&include_translations=1' : ''
      }});
    }
    if (first) {
      out.push({ json: {
        project_id: p.project_id,
        project_name: p.name,
        base_lang: base,
        qa_type: '__control_invalid__',
        qa_label: '__CONTROL__',
        extra: ''
      }});
      first = false;
    }
  }
}
return out;

const LABELS = ['Placeholders', 'HTML', 'Missing inline code', 'Double space (translations)'];
const reqs = $('Build QA Requests').all();
const res = $input.all();
const rows = {};
const projIds = {};
const order = [];
const failed = [];
const truncated = [];
let controlStatus = null;
let inheritedSkipped = 0;
let htmlProjectsSkipped = 0;
let pseudoOnlySkipped = 0;
let frenchSpacingSkipped = 0;
let supOnlySkipped = 0;
const PSEUDO = { 'pst': 1, 'ps': 1, 'ps_ps': 1, 'ps-ps': 1, 'xx': 1, 'zz': 1, 'qps': 1 };
function isPseudo(iso) {
  const s = (iso || '').toLowerCase().trim();
  if (PSEUDO[s]) { return true; }
  return s.indexOf('pseudo') >= 0 || s.indexOf('_ps') >= 0 || s.indexOf('-ps') >= 0;
}
const PH = /%\d+\$[a-zA-Z]|%[sdfi@]|%[A-Za-z_][A-Za-z0-9_]*%|\{\{[^{}]+\}\}|\{[^{}]*\}|\[\[[A-Za-z0-9_.-]+\]\]|\[[A-Za-z0-9_.-]+\]/g;
const TAG = /<\/?([a-zA-Z][a-zA-Z0-9]*)\b[^>]*>/g;
const HTML_IGNORE = { 'sup': 1 };
const CODE = /`[^`\n]*`|<code\b[^>]*>[\s\S]*?<\/code>/g;
const FR = /^fr([-_]|$)/;
const SP = '[ \\u00a0\\u202f\\u2009\\u2007\\u2008]';
const FR_BEFORE = new RegExp(SP + '+(?=[;:!?%\\u00bb\\u20ac])', 'g');
const FR_AFTER = new RegExp('\\u00ab' + SP + '+', 'g');
function stripFrenchSpacing(v) {
  return v.replace(FR_BEFORE, '').replace(FR_AFTER, '\u00ab');
}
function inv(str, re, byName, ignore) {
  const m = {};
  let x;
  re.lastIndex = 0;
  while ((x = re.exec(str)) !== null) {
    const t = byName ? x[1].toLowerCase() : x[0];
    if (ignore && ignore[t]) { continue; }
    m[t] = (m[t] || 0) + 1;
  }
  return m;
}
function differs(a, b) {
  const ks = {};
  for (const k in a) { ks[k] = 1; }
  for (const k in b) { ks[k] = 1; }
  for (const k in ks) { if ((a[k] || 0) !== (b[k] || 0)) { return true; } }
  return false;
}
function localesForKey(k, baseLang, kind) {
  let src = null;
  const tgts = [];
  for (const tr of (k.translations || [])) {
    const v = (typeof tr.translation === 'string') ? tr.translation : '';
    const iso = (tr.language_iso || '').toLowerCase();
    if (iso === baseLang) { src = v; }
    else { tgts.push({ iso: iso, v: v, pseudo: isPseudo(iso) }); }
  }
  const out = { real: [], pseudo: 0, supOnly: 0 };
  if (src === null) { return out; }
  const byName = (kind === 'HTML');
  let re = PH;
  if (byName) { re = TAG; }
  else if (kind === 'Missing inline code') { re = CODE; }
  const ignore = byName ? HTML_IGNORE : null;
  const siReal = inv(src, re, byName, ignore);
  const siFull = ignore ? inv(src, re, byName, null) : siReal;
  for (const t of tgts) {
    if (!t.v || !t.v.trim()) { continue; }
    const tReal = inv(t.v, re, byName, ignore);
    if (differs(siReal, tReal)) {
      if (t.pseudo) { out.pseudo++; } else { out.real.push(t.iso); }
      continue;
    }
    if (!ignore || t.pseudo) { continue; }
    if (differs(siFull, inv(t.v, re, byName, null))) { out.supOnly++; }
  }
  return out;
}
for (let i = 0; i < res.length; i++) {
  const pi = res[i].pairedItem;
  let idx = i;
  if (pi && typeof pi === 'object' && typeof pi.item === 'number') { idx = pi.item; }
  else if (typeof pi === 'number') { idx = pi; }
  const metaItem = reqs[idx] || reqs[i];
  if (!metaItem) { continue; }
  const meta = metaItem.json;
  const r = res[i].json || {};
  const hdr = r.headers || {};
  if (meta.qa_label === '__CONTROL__') { controlStatus = r.statusCode; continue; }
  const raw = hdr['x-pagination-total-count'];
  let total = null;
  if (r.statusCode === 200 && raw !== undefined && raw !== null) {
    const n = parseInt(raw, 10);
    if (!isNaN(n)) { total = n; }
  }
  if (total === null) { failed.push(meta.project_name + ' / ' + meta.qa_label); }
  const keys = (r.body && r.body.keys) ? r.body.keys : [];
  if (total !== null && total > keys.length) { truncated.push(meta.project_name + ' / ' + meta.qa_label); }
  if (!rows[meta.project_name]) { rows[meta.project_name] = {}; order.push(meta.project_name); }
  projIds[meta.project_name] = meta.project_id;
  const loc = {};
  let count = 0;
  let unattr = 0;
  if (meta.qa_label === 'Double space') {
    for (const k of keys) {
      if (k.is_archived) { continue; }
      let srcHas = false;
      const hits = [];
      let pseudoHit = false;
      for (const tr of (k.translations || [])) {
        const v = tr.translation;
        if (typeof v !== 'string') { continue; }
        const iso = (tr.language_iso || '').toLowerCase();
        let text = v;
        if (FR.test(iso)) { text = stripFrenchSpacing(v); }
        if (!/ {2,}/.test(text)) {
          if (FR.test(iso) && / {2,}/.test(v)) { frenchSpacingSkipped++; }
          continue;
        }
        if (iso === meta.base_lang) { srcHas = true; }
        else if (isPseudo(iso)) { pseudoHit = true; }
        else { hits.push(iso); }
      }
      if (srcHas) { if (hits.length > 0) { inheritedSkipped++; } continue; }
      if (hits.length === 0) { if (pseudoHit) { pseudoOnlySkipped++; } continue; }
      count++;
      for (const iso of hits) { loc[iso] = (loc[iso] || 0) + 1; }
    }
    rows[meta.project_name]['Double space (translations)'] =
      (total === null) ? null : { n: count, loc: loc, unattr: 0 };
  } else {
    for (const k of keys) {
      if (k.is_archived) { continue; }
      const ls = localesForKey(k, meta.base_lang, meta.qa_label);
      if (ls.real.length === 0 && ls.pseudo > 0) { pseudoOnlySkipped++; continue; }
      if (ls.real.length === 0 && ls.supOnly > 0) { supOnlySkipped++; continue; }
      count++;
      if (ls.real.length === 0) { unattr++; continue; }
      for (const iso of ls.real) { loc[iso] = (loc[iso] || 0) + 1; }
    }
    rows[meta.project_name][meta.qa_label] =
      (total === null) ? null : { n: count, loc: loc, unattr: unattr };
  }
}
for (const name of order) {
  const s = name.toLowerCase();
  if (s.indexOf('html') >= 0 || s.indexOf('legal page') >= 0) { htmlProjectsSkipped++; }
}
const totals = {};
for (const l of LABELS) { totals[l] = 0; }
const flagged = [];
for (const name of order) {
  const r = rows[name];
  let sum = 0;
  for (const l of LABELS) {
    const c = r[l];
    if (c && typeof c.n === 'number') { sum += c.n; totals[l] += c.n; }
  }
  if (sum > 0) { flagged.push(name); }
}
return [{ json: {
  rows: rows,
  project_ids: projIds,
  totals: totals,
  failed: failed,
  failures: failed.length,
  truncated: truncated,
  project_count: order.length,
  flagged_count: flagged.length,
  control_status: controlStatus,
  zeros_are_trustworthy: controlStatus === 400,
  archived_excluded: true,
  inherited_from_source_skipped: inheritedSkipped,
  html_projects_excluded_from_double_space: htmlProjectsSkipped,
  pseudo_only_keys_skipped: pseudoOnlySkipped,
  french_punctuation_spacing_skipped: frenchSpacingSkipped,
  sup_only_html_keys_skipped: supOnlySkipped
}}];
